import os
import pandas as pd


def solve(data_dir):
    file_path = os.path.join(data_dir, "ventas_wide.csv")
    df = pd.read_csv(file_path)

    # Las columnas de meses son todas excepto 'categoria'
    meses = [c for c in df.columns if c != "categoria"]

    resultado = {}
    for _, row in df.iterrows():
        cat = row["categoria"]
        total = 0
        for mes in meses:
            val = row[mes]
            if isinstance(val, str):
                # Limpiamos el formato '$ 38.954.795'
                val_limpio = (
                    val.replace("$", "").replace(".", "").strip()
                )
                total += int(val_limpio)
            else:
                total += int(val)
        resultado[cat] = total

    return resultado
